def eval_temp(fahrenheit: float = 32.0) -> dict:
    status = "FREEZING" if fahrenheit <= 32.0 else "COMFORTABLE" if fahrenheit < 85.0 else "HOT"
    return {"fahrenheit": fahrenheit, "classification": status}

